<template>
  <div class="tabs">
    <ul class="tabs_header tabDraggable">
      <li class="tab_header" v-for="tab in tabTitles" :key="tab.title" :class="{selectedFugi: selectedTitle === 'Fugitive', selected: tab.title === selectedTitle}" @click="selectedTitle = tab.title">
        {{ tab.title }}
      </li>
    </ul>
    <slot/>
  </div>
</template>

<script>
import { ref, provide } from 'vue';

export default {
  name: "VehiclesTabsWrapper",
  setup(props, {slots}) {
    const tabTitles = ref(slots.default().map((tab) => tab.props))
    const selectedTitle = ref(tabTitles.value[0].title)

    provide("selectedTitle", selectedTitle)
    return {
      selectedTitle,
      tabTitles
    }
  }
}
</script>

<style scoped lang="scss">
.tabs {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  position: relative;
}

.tabs_header {
  display: flex;
  width: 100%;
  justify-content: center;
  align-items: center;
  color: $gray-text;
  //border-bottom: 1px solid $sago-gray2;
  font-weight: bold;

  position: absolute;
  top: -40px;
  z-index: 150;

  .selected {
    transition: all 0.4s;
    transition-property: color,text-shadow;
    color: $white-text;
    //border-bottom: 1px solid #2d6ae3;
    text-shadow: 0 0 5px $white-text;
  }

  .selectedFugi {
    //border-color: #cb4040;
  }

  .tab_header {
    margin: 0px 10px 0 10px;
    display: grid;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    font-size: 20px;
  }
}
</style>