<template>
  <div class="tabs">
    <nav class="tabs_header" @mouseleave="hoverOverCord($event)">
      <div class="logo">
        <img @mouseover="logoURL = `https://i.imgur.com/2sSNYzF.png`" @mouseleave="logoURL = `https://i.imgur.com/S9m1NVy.png`" :src="logoURL" alt="lscc" />
      </div>
      <a @mouseover="hoverCord($event)" class="tab_header" v-for="tab in tabTitles" :key="tab.title" :class="{ selected: tab.title === selectedTitle }" @click="clickHandle($event, tab.title)">
        <i :class="['bx', tab.icon]"></i>
        {{ tab.title }}
      </a>
      <div :style="{ top: top, height: height }" id="slidertab" class="animation start-home"></div>
    </nav>
    <div class="tab-content">
      <div class="top">
        {{ selectedTitle }}
      </div>
      <div class="bottom">
        <slot />
      </div>
    </div>
  </div>
</template>

<script>
import { ref, provide } from "vue";

export default {
  name: "TabsWrapper",
  methods: {
    hoverCord(e) {
      this.top = `${(e.target.tagName === "I" ? e.target.parentElement.getBoundingClientRect().top : e.target.getBoundingClientRect().top) + window.scrollY - 91}px`;
      this.height = `${(e.target.tagName === "I" ? e.target.parentElement.offsetHeight : e.target.offsetHeight) + 15}px`;
    },
    clickHandle(e, title) {
      this.selectedTitle = title;
      let top = `${(e.target.tagName === "I" ? e.target.parentElement.getBoundingClientRect().top : e.target.getBoundingClientRect().top) + window.scrollY - 91}px`;
      let height = `${(e.target.tagName === "I" ? e.target.parentElement.offsetHeight : e.target.offsetHeight) + 15}px`;
      console.log(top, height);
      this.selTop = top;
      this.selHeight = height;
    },
    hoverOverCord() {
      this.top = this.selTop;
      this.height = this.selHeight;
    },
  },
  data() {
    return {
      logoURL: `https://i.imgur.com/S9m1NVy.png`,
      top: "78.5px",
      height: "65px",
      selTop: "78.5px",
      selHeight: "65px",
    };
  },
  setup(props, { slots }) {
    const tabTitles = ref(slots.default().map((tab) => tab.props));
    const selectedTitle = ref(tabTitles.value[0].title);

    provide("selectedTitle", selectedTitle);
    provide("tabTitles", tabTitles);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.top {
  height: 60px;
  display: flex;
  align-items: center;
  padding: 20px 0px 20px 30px;
  font-size: 22px;
  color: #fff;
  //border-bottom: 1px solid $sago-gray2;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
}

.bottom {
  background: $background;
  border-radius: 15px;
  flex: 1;
  //padding: 10px;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px inset;
  overflow: visible !important;
  position: relative;
}

.tab-content {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.animation {
  position: absolute;
  height: 70px;
  width: 100%;
  /* height: 5px; */
  top: 0;
  /* bottom: 0; */
  z-index: 1;
  background: rgba($background, 0.5);
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
  transition: all 0.5s ease 0s;
}

.tabs {
  font-family: "Nunito", sans-serif;
  font-weight: bold;
  display: flex;
  height: 100%;
  width: 100%;
}

.bx {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 27px;
}

.logo {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 10px 0px 5px 0px;

  //background: #2d6ae3;

  img {
    width: 50px;
    -webkit-user-drag: none;
  }
}

.tabs_header {
  height: 100%;
  width: 120px;
  color: $gray-text;
  position: relative;
  //border-right: 1px solid $sago-gray2;
  font-size: 15px;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;

  .selected {
    color: $white-text;
    transition: 0.4s;
    transition-property: color, text-shadow;
    //border-right: 1px solid #2d6ae3;

    text-shadow: 0 0 5px $white-text;
  }

  .tab_header {
    display: grid;
    justify-content: center;
    align-items: center;
    height: 50px;
    margin: 20px 0px;
    cursor: pointer;
    z-index: 999;
    position: relative;

    .bx {
      padding: 8px 0px;
    }
  }
}
</style>
