    selectBuy(name) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuSelectLoadout", name, this.teamid);
    },
  },
  data() {
    return {
      selectedLoadout: null,
      loadouts: [],
    };
  },
};

